package two_instances__SeL4.two_instances

import org.sireum._
import art._
import two_instances__SeL4._
import two_instances__SeL4.two_instances.{w_t_i_p1_worker => component}

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@datatype class w_t_i_p1_worker_Bridge(
  val id: Art.BridgeId,
  val name: String,
  val dispatchProtocol: DispatchPropertyProtocol,
  val dispatchTriggers: Option[ISZ[Art.PortId]],

  ) extends Bridge {

  val ports : Bridge.Ports = Bridge.Ports(
    dataIns = ISZ[art.UPort](),

    dataOuts = ISZ[art.UPort](),

    eventIns = ISZ[art.UPort](),

    eventOuts = ISZ[art.UPort]()
  )

  val initialization_api : w_t_i_Initialization_Api = {
    val api = w_t_i_Initialization_Api(
      id,
    )
    w_t_i_p1_worker_Bridge.c_initialization_api = Some(api)
    api
  }

  val operational_api : w_t_i_Operational_Api = {
    val api = w_t_i_Operational_Api(
      id,
    )
    w_t_i_p1_worker_Bridge.c_operational_api = Some(api)
    api
  }

  val entryPoints : Bridge.EntryPoints =
    w_t_i_p1_worker_Bridge.EntryPoints(
      id,

      dispatchTriggers,

      initialization_api,
      operational_api)
}

object w_t_i_p1_worker_Bridge {

  var c_initialization_api: Option[w_t_i_Initialization_Api] = None()
  var c_operational_api: Option[w_t_i_Operational_Api] = None()

  @datatype class EntryPoints(
    w_t_i_p1_worker_BridgeId : Art.BridgeId,
    dispatchTriggers : Option[ISZ[Art.PortId]],
    initialization_api: w_t_i_Initialization_Api,
    operational_api: w_t_i_Operational_Api) extends Bridge.EntryPoints {

    val dataInPortIds: ISZ[Art.PortId] = IS()

    val eventInPortIds: ISZ[Art.PortId] = IS()

    val dataOutPortIds: ISZ[Art.PortId] = IS()

    val eventOutPortIds: ISZ[Art.PortId] = IS()

    def initialise(): Unit = {
      // implement the following method in 'component':  def initialise(api: w_t_i_Initialization_Api): Unit = {}
      component.initialise(initialization_api)
      Art.sendOutput(eventOutPortIds, dataOutPortIds)
    }

    def compute(): Unit = {
      Art.receiveInput(eventInPortIds, dataInPortIds)

      // implement the following in 'component':  def timeTriggered(api: w_t_i_Operational_Api): Unit = {}
      component.timeTriggered(operational_api)

      Art.sendOutput(eventOutPortIds, dataOutPortIds)
    }

    def finalise(): Unit = {
      // implement the following method in 'component':  def finalise(api: w_t_i_Operational_Api): Unit = {}
      component.finalise(operational_api)
    }

    override
    def testInitialise(): Unit = {
      // implement the following method in 'component':  def initialise(api: w_t_i_Initialization_Api): Unit = {}
      component.initialise(initialization_api)
      Art.releaseOutput(eventOutPortIds, dataOutPortIds)
    }

    override
    def testCompute(): Unit = {
      Art.receiveInput(eventInPortIds, dataInPortIds)

      // implement the following in 'component':  def timeTriggered(api: w_t_i_Operational_Api): Unit = {}
      component.timeTriggered(operational_api)

