void sb_thread_calendar() {
  if ((aadl_calendar_counter % (2 / aadl_tick_interval)) == 0) {
    sb_p1_worker_periodic_dispatch_notification_emit();
  }
  if ((aadl_calendar_counter % (2 / aadl_tick_interval)) == 0) {
    sb_p2_worker_periodic_dispatch_notification_emit();
